/**
 * Babylon.js 3D 모드형상 렌더러
 *
 * 참조: 컨버전전략.md §7.3, §15 stgen 재활용 패턴
 *
 * stgen dxfRenderer.ts 패턴:
 * - Engine + Scene 초기화
 * - useRightHandedSystem (구조공학 좌표계)
 * - FreeCamera (직교/원근 전환)
 * - 정점색 전용 경량 셰이더 + 양면 렌더링
 */

import { Engine } from "@babylonjs/core/Engines/engine";
import { Scene } from "@babylonjs/core/scene";
import { FreeCamera } from "@babylonjs/core/Cameras/freeCamera";
import { Vector3 } from "@babylonjs/core/Maths/math.vector";
import { Color3, Color4 } from "@babylonjs/core/Maths/math.color";
import { Mesh } from "@babylonjs/core/Meshes/mesh";
import { VertexData } from "@babylonjs/core/Meshes/mesh.vertexData";
import { CreateLines } from "@babylonjs/core/Meshes/Builders/linesBuilder";
import { createVertexColorMaterial } from "./vertexColorMaterial";

export interface ModeShape3DData {
    nodes: number[][];    // [[node#, x, z, ...], ...]
    elems: number[][];    // [[elem#, ni, nj, t, mat], ...]
    modeVec: number[];    // 모드형상 벡터
    length: number;       // 부재 길이
    BC: string;           // 경계조건
    scale?: number;       // 변위 스케일
}

export class ModeShape3DRenderer {
    private _engine: Engine | null = null;
    private _scene: Scene | null = null;
    private _camera: FreeCamera | null = null;
    private _canvas: HTMLCanvasElement;
    private _mesh: Mesh | null = null;
    private _wireframes: Mesh[] = [];

    // 마우스 회전 상태
    private _isDragging = false;
    private _isPanning = false;
    private _lastMouseX = 0;
    private _lastMouseY = 0;
    private _rotX = -0.5;
    private _rotY = 0.4;
    private _distance = 30;
    private _targetX = 0;
    private _targetY = 0;
    private _targetZ = 0;
    private _resizeObserver: ResizeObserver | null = null;
    private _inputAbort: AbortController | null = null;

    constructor(canvas: HTMLCanvasElement) {
        this._canvas = canvas;
    }

    init(): void {
        if (this._engine) { return; }

        // stgen 패턴: Engine 옵션
        this._engine = new Engine(this._canvas, true, {
            stencil: false,
        } as any);

        this._scene = new Scene(this._engine);
        this._scene.useRightHandedSystem = true;
        this._scene.clearColor = new Color4(0.95, 0.95, 0.95, 1); // 흰색 배경

        // 카메라
        this._camera = new FreeCamera("cam", new Vector3(0, 0, 0), this._scene);
        this._camera.minZ = 0.01;
        this._camera.maxZ = 10000;
        this._camera.detachControl();

        // 마우스 인터랙션
        this._setupMouseControls();

        // 렌더 루프
        this._engine.runRenderLoop(() => {
            this._updateCamera();
            this._scene!.render();
        });

        // 리사이즈
        this._resizeObserver = new ResizeObserver(() => this._engine?.resize());
        this._resizeObserver.observe(this._canvas);
    }

    render(data: ModeShape3DData): void {
        if (!this._scene) { this.init(); }

        // 기존 메시 제거
        this._clearMeshes();

        const { nodes, elems, modeVec, length, BC } = data;
        const dispScale = data.scale || 0.3;
        const nnodes = nodes.length;
        const skip = 2 * nnodes;

        // 단면 크기 계산
        const xs = nodes.map(n => n[1]);
        const zs = nodes.map(n => n[2]);
        const xMid = (Math.min(...xs) + Math.max(...xs)) / 2;
        const zMid = (Math.min(...zs) + Math.max(...zs)) / 2;
        const sectionSize = Math.max(
            Math.max(...xs) - Math.min(...xs),
            Math.max(...zs) - Math.min(...zs)
        ) || 1;

        // 반파장이 단면보다 짧으면 반파 수를 늘려서 부재를 충분히 길게 표시
        const minDisplayLength = sectionSize * 2;
        const nHalfWaves = Math.max(1, Math.ceil(minDisplayLength / length));
        const displayLength = length * nHalfWaves;

        // 반파당 최소 4개 샘플 보장 (앨리어싱 방지)
        const nSteps = Math.max(20, nHalfWaves * 4);

        // 카메라: 실제 치수 기반 자동 조정
        const diagonal = Math.sqrt(sectionSize * sectionSize + displayLength * displayLength);
        this._distance = diagonal * 1.5;
        this._targetX = 0;
        this._targetY = 0;
        this._targetZ = displayLength / 2; // 부재 중앙을 바라봄

        // 변위 추출
        const uDisp: number[] = [];
        const wDisp: number[] = [];
        for (let n = 0; n < nnodes; n++) {
            uDisp.push((modeVec[2 * n] || 0) * dispScale * sectionSize);
            wDisp.push((modeVec[skip + 2 * n] || 0) * dispScale * sectionSize);
        }

        // 요소 쌍
        const elemPairs: [number, number][] = [];
        for (const e of elems) {
            const ni = e[1] - 1;
            const nj = e[2] - 1;
            if (ni >= 0 && ni < nnodes && nj >= 0 && nj < nnodes) {
                elemPairs.push([ni, nj]);
            }
        }

        // 형상함수 (다중 반파 지원)
        const shapeFunc = (y: number): number => {
            const yLocal = y % length;
            const halfIdx = Math.floor(y / length);
            const sign = (halfIdx % 2 === 0) ? 1 : -1;
            const ya = yLocal / length;
            let val: number;
            if (BC === 'C-C') { val = Math.sin(Math.PI * ya) ** 2; }
            else if (BC === 'C-F') { val = 1 - Math.cos(Math.PI * ya / 2); }
            else if (BC === 'S-C') { val = Math.sin(Math.PI * ya) + ya * Math.sin(2 * Math.PI * ya) / (1 + ya); }
            else { val = Math.sin(Math.PI * ya); }
            return sign * val;
        };

        // === 변형 메시 (면) ===
        const positions: number[] = [];
        const indices: number[] = [];
        const colors: number[] = [];
        const maxDisp = Math.max(
            ...uDisp.map(Math.abs),
            ...wDisp.map(Math.abs)
        ) || 1;

        // 각 요소에 대해 길이방향 메시 생성
        for (const [ni, nj] of elemPairs) {
            const baseIdx = positions.length / 3;

            for (let s = 0; s <= nSteps; s++) {
                const y = (s / nSteps) * displayLength;
                const Ym = shapeFunc(y);

                // 절점 i
                const dxi = uDisp[ni] * Ym;
                const dzi = wDisp[ni] * Ym;
                positions.push(
                    xs[ni] + dxi - xMid,
                    y - displayLength / 2,
                    zs[ni] + dzi - zMid
                );

                // 절점 j
                const dxj = uDisp[nj] * Ym;
                const dzj = wDisp[nj] * Ym;
                positions.push(
                    xs[nj] + dxj - xMid,
                    y - displayLength / 2,
                    zs[nj] + dzj - zMid
                );

                // 색상: 변위 크기 → 은색(0) → 구리/금색(1) 금속 계열
                const magI = Math.sqrt(dxi * dxi + dzi * dzi) / maxDisp;
                const magJ = Math.sqrt(dxj * dxj + dzj * dzj) / maxDisp;
                // 은색(0.75,0.75,0.78) → 구리색(0.85,0.55,0.25)
                colors.push(0.75 + magI * 0.10, 0.75 - magI * 0.20, 0.78 - magI * 0.53, 1);
                colors.push(0.75 + magJ * 0.10, 0.75 - magJ * 0.20, 0.78 - magJ * 0.53, 1);
            }

            // 삼각형 인덱스
            for (let s = 0; s < nSteps; s++) {
                const a = baseIdx + s * 2;
                const b = a + 1;
                const c = a + 2;
                const d = a + 3;
                indices.push(a, c, b);
                indices.push(b, c, d);
            }
        }

        // Babylon.js 메시 생성
        const mesh = new Mesh("modeShape", this._scene!);
        const vertexData = new VertexData();
        vertexData.positions = positions;
        vertexData.indices = indices;
        vertexData.colors = colors;
        vertexData.applyToMesh(mesh);

        mesh.material = createVertexColorMaterial("modeShapeMaterial", this._scene!);
        mesh.hasVertexAlpha = false;
        this._mesh = mesh;

        // === 미변형 와이어프레임 ===
        for (const [ni, nj] of elemPairs) {
            const linePoints: Vector3[] = [];
            for (let s = 0; s <= nSteps; s++) {
                const y = (s / nSteps) * displayLength;
                linePoints.push(new Vector3(
                    (xs[ni] + xs[nj]) / 2 - xMid,
                    y - displayLength / 2,
                    (zs[ni] + zs[nj]) / 2 - zMid
                ));
            }
        }

        // 단면 윤곽선 (시작/끝)
        for (const yPos of [0, displayLength]) {
            const Ym = shapeFunc(yPos);
            const points: Vector3[] = [];
            // 절점 순서대로 연결
            for (let n = 0; n < nnodes; n++) {
                const dx = uDisp[n] * Ym;
                const dz = wDisp[n] * Ym;
                points.push(new Vector3(
                    xs[n] + dx - xMid,
                    yPos - length / 2,
                    zs[n] + dz - zMid
                ));
            }
            if (points.length > 1) {
                const lines = CreateLines(
                    `outline_${yPos}`,
                    { points },
                    this._scene!
                );
                lines.color = new Color3(0.2, 0.2, 0.25);
                this._wireframes.push(lines);
            }
        }
    }

    private _clearMeshes(): void {
        this._mesh?.dispose(false, true);
        this._mesh = null;
        for (const w of this._wireframes) { w.dispose(false, true); }
        this._wireframes = [];
    }

    private _updateCamera(): void {
        if (!this._camera) { return; }
        const x = this._targetX + this._distance * Math.cos(this._rotY) * Math.sin(this._rotX);
        const y = this._targetY + this._distance * Math.sin(this._rotY);
        const z = this._targetZ + this._distance * Math.cos(this._rotY) * Math.cos(this._rotX);
        this._camera.position = new Vector3(x, y, z);
        this._camera.setTarget(new Vector3(this._targetX, this._targetY, this._targetZ));
    }

    private _setupMouseControls(): void {
        this._inputAbort?.abort();
        this._inputAbort = new AbortController();
        const signal = this._inputAbort.signal;

        this._canvas.addEventListener('pointerdown', (e: PointerEvent) => {
            // 우클릭 또는 Shift+좌클릭 → 팬, 좌클릭 → 회전
            if (e.button === 2 || (e.button === 0 && e.shiftKey)) {
                this._isPanning = true;
                this._isDragging = false;
            } else if (e.button === 0) {
                this._isDragging = true;
                this._isPanning = false;
            }
            this._lastMouseX = e.clientX;
            this._lastMouseY = e.clientY;
            e.preventDefault();
        }, { signal });

        this._canvas.addEventListener('pointermove', (e: PointerEvent) => {
            const dx = e.clientX - this._lastMouseX;
            const dy = e.clientY - this._lastMouseY;
            this._lastMouseX = e.clientX;
            this._lastMouseY = e.clientY;

            if (this._isDragging) {
                // 회전
                this._rotX += dx * 0.005;
                this._rotY = Math.max(-1.5, Math.min(1.5, this._rotY + dy * 0.005));
            } else if (this._isPanning) {
                // 팬 — 카메라 평면 기준 이동
                const panSpeed = this._distance * 0.002;
                const sinR = Math.sin(this._rotX);
                const cosR = Math.cos(this._rotX);
                this._targetX += (-dx * cosR) * panSpeed;
                this._targetZ += (dx * sinR) * panSpeed;
                this._targetY += dy * panSpeed;
            }
        }, { signal });

        this._canvas.addEventListener('pointerup', () => {
            this._isDragging = false;
            this._isPanning = false;
        }, { signal });
        this._canvas.addEventListener('pointerleave', () => {
            this._isDragging = false;
            this._isPanning = false;
        }, { signal });

        // 우클릭 컨텍스트 메뉴 방지
        this._canvas.addEventListener('contextmenu', (e) => e.preventDefault(), { signal });

        this._canvas.addEventListener('wheel', (e: WheelEvent) => {
            this._distance *= e.deltaY > 0 ? 1.1 : 0.9;
            this._distance = Math.max(0.5, Math.min(50000, this._distance));
            e.preventDefault();
        }, { signal });

        // 더블클릭 → 뷰 초기화
        this._canvas.addEventListener('dblclick', () => {
            this._targetX = 0;
            this._targetY = 0;
            this._targetZ = 0;
            this._rotX = -0.5;
            this._rotY = 0.4;
        }, { signal });
    }

    dispose(): void {
        this._inputAbort?.abort();
        this._inputAbort = null;
        this._resizeObserver?.disconnect();
        this._resizeObserver = null;
        this._clearMeshes();
        this._scene?.dispose();
        this._engine?.dispose();
        this._engine = null;
        this._scene = null;
    }
}
